// Classroom checkout rendered inside the normal Two-Hands storefront.
// Every operation stays under /api/demo; live accounts and orders are untouched.
export function createMainDemoUI({getState,request,refresh,openModal,closeModal,form,toast,esc,money,photo,setMode}){
 const state=()=>getState();
 const names={awaiting_payment:'รอชำระเงินจำลอง',paid_demo:'ชำระเงินจำลองแล้ว',preparing:'ร้านกำลังเตรียมสินค้า',ready:'พร้อมรับสินค้า',completed:'รับสินค้าสำเร็จ',cancelled:'ยกเลิกแล้ว'};
 const btn=(action,label,id='',extra='')=>`<button type="button" class="button outline" data-teach="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
 const note='<div class="notice">DEMO · ทดลองเพื่อการนำเสนอ ไม่มีการรับเงินจริง ไม่ต้องกรอกเลขบัตรหรือข้อมูลธนาคาร</div>';
 async function send(path,body={},method='POST'){if(!state().demo)throw Error('กรุณาเปิดโหมด Demo ก่อน');const result=await request('/demo'+path,method,body);await refresh();return result;}
 async function role(value){if(state().role!==value)await send('/role',{role:value});}
 function account(){openModal('ทดลองซื้อขายในเว็บหลัก',`${note}<p>บทบาทปัจจุบัน: <strong>${state().role==='seller'?'ผู้ขาย':'ผู้ซื้อ'} Demo</strong></p><div class="row-actions">${btn('buyer','ฉันเป็นผู้ซื้อ')}${btn('seller','ฉันเป็นผู้ขาย')}${btn('orders','คำสั่งซื้อของฉัน')}${btn('sales','รายการขายของร้าน')}${btn('sell','ลงขายสินค้าจำลอง')}${btn('listings','สินค้าของฉัน')}${btn('reset','เริ่มสาธิตใหม่')}${btn('live','เข้าสู่ระบบด้วยบัญชีจริง')}</div>`);}
 function product(id){const p=state().products.find(p=>p.id===id);if(!p)return;openModal(p.title,`<div class="detail-layout"><img class="detail-image" src="${esc(photo(p))}" alt="${esc(p.title)}"><div><span class="status-pill pending">สินค้าจำลอง</span><p>${esc(p.description)}</p><p>${esc(p.location)} · ${esc(p.condition)}</p><strong class="detail-price">${money(p.price)}</strong>${note}${p.status==='active'?btn('add','เพิ่มลงตะกร้า',p.id):'<p>สินค้านี้ถูกจองหรือขายแล้วในชุดทดลองนี้</p>'}${btn('cart','เปิดตะกร้า')}</div></div>`);}
 async function cart(){await role('buyer');const items=state().cart.map(id=>state().products.find(p=>p.id===id)).filter(Boolean);openModal('ตะกร้าของคุณ · Demo',`${note}${items.map(p=>`<div class="cart-row"><img src="${esc(photo(p))}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><strong>${money(p.price)}</strong></div>${btn('remove','ลบ',p.id)}</div>`).join('')}${items.length?`<div class="cart-total"><span>ยอดสินค้า</span><strong>${money(items.reduce((sum,p)=>sum+p.price,0))}</strong></div>${btn('checkout','ดำเนินการชำระเงินจำลอง')}`:'<p>ตะกร้าว่าง เลือกสินค้าจากหน้าร้านได้เลย</p>'}`);}
 function checkout(){const items=state().cart.map(id=>state().products.find(p=>p.id===id)).filter(Boolean);if(!items.length)return cart();const key=crypto.randomUUID();form('ยืนยันคำสั่งซื้อ · Demo',`${note}<p>${items.map(p=>`${esc(p.title)} · ${money(p.price)}`).join('<br>')}</p><div class="cart-total"><span>ยอดรวมเบื้องต้น</span><strong>${money(items.reduce((sum,p)=>sum+p.price,0))}</strong></div><p>นัดรับสินค้า · ไม่มีค่าจัดส่ง · ระบบตรวจยอดอีกครั้งก่อนสร้างคำสั่งซื้อ</p>`,'สร้างคำสั่งซื้อและจ่ายเงินจำลอง',async()=>{const result=await send('/orders',{requestKey:key});payment(result.orderId);});}
 function steps(status){const sequence=['awaiting_payment','paid_demo','preparing','ready','completed'];const index=sequence.indexOf(status);return `<ol class="teaching-steps">${['สั่งซื้อ','จ่ายจำลอง','เตรียมสินค้า','พร้อมรับ','รับแล้ว'].map((label,i)=>`<li class="${i<=index?'done':''}">${label}</li>`).join('')}</ol>`;}
 async function orders(sales=false){await role(sales?'seller':'buyer');const list=sales?state().sales:state().orders;openModal(sales?'รายการขายของร้าน · Demo':'คำสั่งซื้อของฉัน · Demo',`${note}<p>${sales?'เมื่อผู้ซื้อจ่ายจำลองแล้ว ให้ร้านเตรียมสินค้าและแจ้งพร้อมรับ':'หลังจ่ายเงินจำลอง สลับเป็นผู้ขายเพื่อเตรียมสินค้า แล้วกลับมายืนยันรับ'}</p>${list.map(o=>`<article class="order-card"><span class="status-pill pending">${esc(names[o.status]||o.status)}</span><p class="teaching-id">คำสั่งซื้อ ${esc(o.id)}</p>${steps(o.status)}<p>${o.items.map(i=>`${esc(i.title)} · ${money(i.price)}`).join('<br>')}</p><div class="cart-total"><span>ยอดรวม</span><strong>${money(o.total)}</strong></div><div class="row-actions">${!sales&&o.status==='awaiting_payment'?btn('pay','ชำระเงินจำลอง',o.id)+btn('cancel','ยกเลิก',o.id):''}${sales&&o.status==='paid_demo'?btn('prepare','เริ่มเตรียมสินค้า',o.id):''}${sales&&o.status==='preparing'?btn('ready','แจ้งพร้อมรับสินค้า',o.id):''}${!sales&&o.status==='ready'?btn('receive','ยืนยันรับสินค้าจำลอง',o.id):''}${o.receiptId?btn('receipt','ดูใบยืนยันจำลอง',o.id):''}</div></article>`).join('')||'<p>ยังไม่มีรายการ เลือกสินค้าจากหน้าร้านเพื่อเริ่มทดลอง</p>'}<div class="row-actions">${btn(sales?'orders':'sales',sales?'สลับไปดูฝั่งผู้ซื้อ':'สลับไปดูฝั่งผู้ขาย')}</div>`);}
 function payment(id){const o=state().orders.find(o=>o.id===id);if(!o)return;openModal('ชำระเงินจำลอง',`${note}<div class="teaching-payment"><strong>DEMO PAYMENT</strong><p>ไม่มี QR ที่โอนเงินจริงได้</p></div><div class="cart-total"><span>ยอดชำระจำลอง</span><strong>${money(o.total)}</strong></div><label class="teaching-method">วิธีชำระ<select id="main-demo-method"><option value="qr_demo">QR จำลอง</option><option value="card_demo">บัตรจำลอง · ไม่กรอกข้อมูลบัตร</option></select></label><p id="main-demo-pay-error" class="form-error" role="alert"></p><div class="row-actions">${btn('paid','จำลองชำระสำเร็จ',id)}${btn('decline','จำลองชำระไม่ผ่าน',id)}</div>`);}
 function receipt(id){const r=state().receipts.find(r=>r.orderId===id),o=state().orders.find(o=>o.id===id);if(!r||!o)return;openModal('ใบยืนยันการชำระเงินจำลอง',`<article class="teaching-receipt"><span class="status-pill pending">DEMO · ไม่ใช่ใบกำกับภาษี</span><h3>Two-Hands</h3><p class="teaching-id">คำสั่งซื้อ ${esc(id)}<br>เลขอ้างอิง ${esc(r.id)}</p><p>${esc(new Date(r.at).toLocaleString('th-TH'))}<br>${r.method==='card_demo'?'บัตรจำลอง':'QR จำลอง'}</p><p>${o.items.map(i=>`${esc(i.title)} · ${money(i.price)}`).join('<br>')}</p><div class="cart-total"><span>ยอดชำระจำลอง</span><strong>${money(r.total)}</strong></div><p>ไม่มีการรับหรือโอนเงินจริง ไม่ใช่หลักฐานชำระเงินจริงหรือใบกำกับภาษี</p></article><div class="row-actions">${btn('orders','คำสั่งซื้อของฉัน')}${btn('sales','ให้ร้านเตรียมสินค้า')}</div>`);}
 async function sell(){await role('seller');form('ลงขายสินค้า · Demo',note+'<label>ชื่อสินค้า<input name="title" required maxlength="90"></label><label>รายละเอียด<textarea name="description" required minlength="10" maxlength="1500"></textarea></label><label>หมวดหมู่<select name="category">'+state().categories.filter(c=>c.id!=='all').map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('')+'</select></label><label>สภาพ<select name="condition"><option>สภาพดีมาก</option><option>เหมือนใหม่</option><option>สภาพดี</option><option>มีตำหนิ</option></select></label><label>ราคา (บาท)<input name="price" type="number" min="1" max="10000000" required></label><label>พื้นที่สมมติ<input name="location" value="กรุงเทพฯ (สาธิต)" required maxlength="120"></label><label>ภาพจากคลังสาธิต<select name="image">'+Object.keys(state().images).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')+'</select></label>','ลงขายจำลอง',async f=>{const b=Object.fromEntries(f);b.price=Number(b.price);await send('/products',b);closeModal();toast('ลงขายแล้วในชุดสาธิต สลับเป็นผู้ซื้อเพื่อทดลองซื้อได้');});}
 async function listings(){await role('seller');const active=state().products,deleted=state().deletedProducts||[];openModal('สินค้าของฉัน · Demo',`${note}<p>ลบสินค้าที่พร้อมขายออกจากหน้าร้านได้ โดยกู้คืนได้จากรายการด้านล่าง สินค้าที่ถูกจองหรือขายแล้วจะลบไม่ได้</p>${active.map(p=>`<article class="order-card"><div class="cart-row"><img src="${esc(photo(p))}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><strong>${money(p.price)}</strong><p>${p.status==='active'?'พร้อมขาย':p.status==='sold'?'ขายแล้ว':'มีการจอง / ซื้อแล้ว'}</p></div></div>${p.status==='active'?btn('delete','ลบสินค้า',p.id):'<p>เก็บไว้เป็นประวัติการซื้อขาย</p>'}</article>`).join('')}<h3>สินค้าที่ลบแล้ว (${deleted.length})</h3>${deleted.map(p=>`<article class="order-card"><strong>${esc(p.title)}</strong><p>${money(p.price)}</p>${btn('restore','กู้คืนสินค้า',p.id)}</article>`).join('')||'<p>ยังไม่มีสินค้าที่ลบ</p>'}`);}
 function deleteProduct(id){const p=state().products.find(p=>p.id===id);if(!p||p.status!=='active')return;form('ยืนยันลบสินค้า',`<h3>${esc(p.title)}</h3><p>${money(p.price)}</p><div class="notice">สินค้าจะถูกซ่อนจากหน้าร้านและนำออกจากตะกร้า กู้คืนได้ในสินค้าของฉัน → สินค้าที่ลบแล้ว</div><label><input type="checkbox" required> ยืนยันลบสินค้านี้ออกจากหน้าร้าน</label>`,'ยืนยันลบสินค้า',async()=>{await send('/products/'+encodeURIComponent(id),{},'DELETE');await listings();toast('ลบสินค้าออกจากหน้าร้านแล้ว');});}
 function reset(){form('เริ่มสาธิตใหม่',note+'<label><input type="checkbox" required> ล้างเฉพาะข้อมูลทดลองของเบราว์เซอร์นี้และเริ่มใหม่</label>','เริ่มสาธิตใหม่',async()=>{await send('/reset');closeModal();toast('เริ่มชุดสาธิตใหม่แล้ว');});}
 async function handle(action,id){
  if(action==='live'){closeModal();return setMode(false);}
  if(!state().demo)return;
  if(action==='buyer'||action==='seller'){await role(action);closeModal();toast('เปลี่ยนเป็น'+(action==='buyer'?'ผู้ซื้อ':'ผู้ขาย')+' Demo แล้ว');return;}
  if(action==='listings')return listings();if(action==='delete')return deleteProduct(id);if(action==='restore'){await send('/products/'+encodeURIComponent(id)+'/restore');await listings();toast('กู้คืนสินค้าแล้ว');return;}if(action==='account')return account();if(action==='cart')return cart();if(action==='checkout')return checkout();if(action==='orders')return orders();if(action==='sales')return orders(true);if(action==='sell')return sell();if(action==='pay')return payment(id);if(action==='receipt')return receipt(id);if(action==='reset')return reset();
  if(action==='add'){await role('buyer');await send('/cart/'+encodeURIComponent(id),{},'PUT');toast('เพิ่มลงตะกร้า Demo แล้ว');return;}
  if(action==='remove'){await send('/cart/'+encodeURIComponent(id),{},'DELETE');return cart();}
  if(action==='paid'||action==='decline'){
   const method=document.querySelector('#main-demo-method').value;await send('/orders/'+encodeURIComponent(id)+'/pay',{method,outcome:action==='paid'?'success':'declined',requestKey:crypto.randomUUID()});
   if(action==='paid')return receipt(id);document.querySelector('#main-demo-pay-error').textContent='จำลองชำระไม่ผ่าน ยังไม่ได้จ่ายเงิน สามารถลองใหม่ได้';return;
  }
  if(action==='prepare'||action==='ready'){await send('/orders/'+encodeURIComponent(id)+'/fulfill',{status:action==='prepare'?'preparing':'ready'});return orders(true);}
  if(action==='cancel'){await send('/orders/'+encodeURIComponent(id)+'/cancel');return orders();}
  if(action==='receive')return form('ยืนยันรับสินค้าจำลอง',note+'<label><input type="checkbox" required> ทดลองยืนยันรับสินค้าจำลองแล้ว</label>','ยืนยันรับจำลอง',async()=>{await send('/orders/'+encodeURIComponent(id)+'/receive');await orders();});
 }
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-teach]');if(!el)return;e.preventDefault();if(el.disabled)return;el.disabled=true;try{await handle(el.dataset.teach,el.dataset.id);}catch(error){toast(error.message);}finally{el.disabled=false;}});
 return {account,product,cart,checkout,listings,orders:()=>orders(),sales:()=>orders(true),sell,reset};
}
